@page "/notifications"
@using BlazorApp.Services
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject NotificationService NotificationSvc
@inject PersistentComponentState ApplicationState

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var notification in _notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item">
                <strong>@notification.Message</strong>
                <small class="text-muted ms-2">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to persist state so prerendered data survives the handoff
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistNotifications);

        // Try to restore persisted state from prerender; if available, skip re-fetching
        if (ApplicationState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            _notifications = restored!;
        }
        else
        {
            // First render (static SSR) — load from service
            _notifications = await NotificationSvc.GetNotificationsAsync();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires in interactive mode, never during static prerender
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        // Determine the latest ID we already have so we only fetch new ones
        var lastSeenId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                // Simulate the server producing a new notification each poll cycle
                NotificationSvc.SimulateNewNotification();

                var newItems = await NotificationSvc.GetNotificationsSinceAsync(lastSeenId);
                if (newItems.Count > 0)
                {
                    _notifications.AddRange(newItems);
                    lastSeenId = newItems.Max(n => n.Id);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        _persistingSubscription.Dispose();

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

